import argparse
import json
import sys
from datetime import date


def parse_since(value):
    try:
        return date.fromisoformat(value)
    except ValueError:
        raise argparse.ArgumentTypeError(
            "invalid date '" + value + "' (expected YYYY-MM-DD)"
        )


def parse_args():
    parser = argparse.ArgumentParser(description="Generate a sales report.")
    parser.add_argument("csv_file", help="path to the sales CSV file")
    parser.add_argument(
        "--format",
        choices=("text", "json"),
        default="text",
        help="output format (default: text)",
    )
    parser.add_argument(
        "--since",
        type=parse_since,
        default=None,
        metavar="YYYY-MM-DD",
        help="only include sales on or after this date",
    )
    return parser.parse_args()


def calculate(path, since):
    d = []
    t = 0
    t2 = 0
    r = {}
    p = {}
    n = 0

    f = open(path)
    lines = f.readlines()
    for i in range(len(lines)):
        if i == 0:
            continue
        l = lines[i].strip().split(",")
        if len(l) < 5:
            continue
        if since is not None:
            try:
                row_date = date.fromisoformat(l[0].strip())
            except ValueError:
                continue
            if row_date < since:
                continue
        try:
            u = int(l[3])
        except:
            continue
        try:
            pr = float(l[4])
        except:
            continue
        amt = u * pr
        if u >= 50:
            amt = amt - amt * 0.1
        else:
            if u >= 10:
                amt = amt - amt * 0.05
        if l[1] == "north":
            tx = amt * 0.07
        elif l[1] == "south":
            tx = amt * 0.05
        elif l[1] == "east":
            tx = amt * 0.06
        elif l[1] == "west":
            tx = amt * 0.08
        else:
            tx = 0
        t = t + amt
        t2 = t2 + tx
        if l[1] in r:
            r[l[1]] = r[l[1]] + amt
        else:
            r[l[1]] = amt
        if l[2] in p:
            p[l[2]] = p[l[2]] + amt
        else:
            p[l[2]] = amt
        d.append(l)
        n = n + 1

    best = None
    bv = 0
    for k in p:
        if p[k] > bv:
            bv = p[k]
            best = k

    return d, t, t2, r, p, n, best, bv


def print_text(t, t2, r, p, n, best, bv):
    print("SALES REPORT")
    print("============")
    print("Rows: " + str(n))
    print("Total revenue: " + str(round(t, 2)))
    print("Total tax: " + str(round(t2, 2)))
    print("")
    print("By region:")
    for k in sorted(r.keys()):
        print("  " + k + ": " + str(round(r[k], 2)))
    print("")
    print("By product:")
    for k in sorted(p.keys()):
        print("  " + k + ": " + str(round(p[k], 2)))
    print("")
    if best is None:
        print("Top product: None")
    else:
        print("Top product: " + best + " (" + str(round(bv, 2)) + ")")


def print_json(t, t2, r, p, n, best):
    report = {
        "rows": n,
        "total_revenue": round(t, 2),
        "total_tax": round(t2, 2),
        "by_region": {k: round(r[k], 2) for k in sorted(r)},
        "by_product": {k: round(p[k], 2) for k in sorted(p)},
        "top_product": best,
    }
    print(json.dumps(report, indent=2))


def go():
    args = parse_args()
    d, t, t2, r, p, n, best, bv = calculate(args.csv_file, args.since)
    if args.format == "json":
        print_json(t, t2, r, p, n, best)
    else:
        print_text(t, t2, r, p, n, best, bv)


go()

